import { decodeUTF8 } from './utils/strings.mjs'
import { isBuffer } from './utils/types.mjs'

export default class BufferView extends DataView {
  static isViewable (param) {
    if (isBuffer(param) || Array.isArray(param) || ArrayBuffer.isView(param)) {
      return true
    }

    return false
  }

  constructor (...params) {
    if (typeof params[0] === 'number' || Array.isArray(params[0])) {
      params[0] = new Uint8Array(params[0])
    }

    if (typeof Buffer !== 'undefined' && params[0] instanceof Buffer) {
      const arrayBuffer = new ArrayBuffer(params[0].byteLength)
      const view = new Uint8Array(arrayBuffer)
      for (let i = 0; i < params[0].byteLength; i++) {
        view[i] = params[0][i]
      }

      params[0] = arrayBuffer
    }

    if (ArrayBuffer.isView(params[0])) {
      params[0] = params[0].buffer
    }

    super(...params)
  }

  getString (offset, maxlength, encoding = 'ascii') {
    const bytes = this.getUint8(offset, maxlength, true)
    let string = ''

    switch (encoding) {
      case 'utf8':
      case 'utf-8':
        string = decodeUTF8(bytes)
        break

      case 'ascii':
      default:
        string = String.fromCharCode(...bytes)
    }

    return string
  }

  getUint8 (offset, length = 1, array = false) {
    const limit = offset + length
    const bytes = []

    if (this.byteLength - limit < 0) return false
    for (let i = offset; i < limit; i++) {
      const byte = DataView.prototype.getUint8.call(this, i)
      bytes.push(byte)
    }

    return bytes.length === 1 && !array ? bytes[0] : bytes
  }

  getInt16 (offset, length = 2, le = false) {
    while (length % 2 !== 0) length -= 1
    const limit = offset + length
    const bytes = []

    if (this.byteLength - limit < 0) return false
    for (let i = offset; i < limit; i += 2) {
      const byte = DataView.prototype.getInt16.call(this, i, le)
      bytes.push(byte)
    }

    return bytes.length === 1 ? bytes[0] : bytes
  }

  getInt32 (offset, length = 4, le = false) {
    while (length % 4 !== 0) length -= 1
    const limit = offset + length
    const bytes = []

    if (this.byteLength - limit < 0) return false
    for (let i = offset; i < limit; i += 4) {
      const byte = DataView.prototype.getInt32.call(this, i, le)
      bytes.push(byte)
    }

    return bytes.length === 1 ? bytes[0] : bytes
  }

  getUint32 (offset, length = 4, le = false) {
    while (length % 4 !== 0) length -= 1
    const limit = offset + length
    const bytes = []

    if (this.byteLength - limit < 0) return false
    for (let i = offset; i < limit; i += 4) {
      const byte = DataView.prototype.getUint32.call(this, i, le)
      bytes.push(byte)
    }

    return bytes.length === 1 ? bytes[0] : bytes
  }

  getUint64 (offset, length = 8, le = false) {
    while (length % 8 !== 0) length -= 1
    const limit = offset + length
    const bytes = []

    if (this.byteLength - limit < 0) return false
    for (let i = offset; i < limit; i += 8) {
      const byte = DataView.prototype.getBigUint64.call(this, i, le)
      bytes.push(byte)
    }

    return bytes.length === 1 ? bytes[0] : bytes
  }
}
